recipe:
let
  root = /home/dylan/src/aos/.worktrees/codex/bazel-integration-722;
  pkgs = (import root {}).pkgs;
  nativeLibraries = [pkgs.openssl pkgs.sqlite pkgs.zstdStaticMultithread];
  nativeTools = [pkgs.pkg-config];
  cargoSetup = ''
    export OPENSSL_DIR=${pkgs.openssl} OPENSSL_NO_VENDOR=1
    export LIBSQLITE3_SYS_USE_PKG_CONFIG=1 ZSTD_SYS_USE_PKG_CONFIG=1
  '';
  cargoSource = import (root + "/pkgs/tools/crucible/_cargo-source.nix") {inherit (pkgs) lib;};
  tests = import (root + "/tests/build/_bazel-cargo-oracle.nix") {
    inherit pkgs cargoSource nativeLibraries nativeTools;
    cargoSetup = cargoSetup + ''
      export RUST_TEST_THREADS="$NIX_BUILD_CORES"
    '';
    pname = "aos-bazel-hub-db-cargo-baseline";
    packages = ["aos-hub-db"];
  };
  production = pkgs.mkDerivation {
    pname = "aos-bazel-hub-db-production-cargo-baseline";
    version = "1";
    src = cargoSource;
    buildDeps = [pkgs.rust pkgs.sed] ++ nativeTools;
    runtimeDeps = nativeLibraries;
    sharedBuildCache = false;
    dontStrip = true;
    dontPatchELF = true;
    dontNukeRefs = true;
    phases = [{
      name = "compile";
      script = ''
        cp -R "$src" source
        chmod -R u+w source
        cd source
        export CARGO_HOME="$TMPDIR/cargo" CARGO_TARGET_DIR="$TMPDIR/target"
        mkdir -p "$CARGO_HOME" .cargo "$out"
        sed 's|@vendor@|${pkgs.aos.passthru.cargoDeps}|g' \
          ${pkgs.aos.passthru.cargoDeps}/.cargo/config.toml > .cargo/config.toml
        ${cargoSetup}
        cargo build --frozen --offline --manifest-path crates/Cargo.toml --lib -p aos-hub-db \
          --jobs "$NIX_BUILD_CORES" --message-format=json > "$out/cargo-messages.jsonl"
      '';
    }];
  };
in { builds = [tests production]; inherit tests production; }
